import{_ as t,a}from"./chunks/ugso_trigger_value.Ddcuu3_H.js";import{_ as i,o as r,c as s,a3 as o}from"./chunks/framework.BlfGB29P.js";const n="/assets/blocks-for-ha/schedule-en.png",d="/assets/blocks-for-ha/schedule-dark-en.png",f=JSON.parse('{"title":"Date and time","description":"Time blocks, HA timezone and ioBroker comparison.","frontmatter":{"title":"Date and time","description":"Time blocks, HA timezone and ioBroker comparison."},"headers":[],"relativePath":"en/projects/blocks-for-ha/time.md","filePath":"en/projects/blocks-for-ha/time.md","lastUpdated":1793006827000}'),l={name:"en/projects/blocks-for-ha/time.md"};function c(m,e,p,h,u,g){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="date-and-time" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and time&quot;">​</a></h1><h2 id="schedules-and-triggers-since-0-1-60" tabindex="-1">Schedules and triggers since 0.1.60 <a class="header-anchor" href="#schedules-and-triggers-since-0-1-60" aria-label="Permalink to &quot;Schedules and triggers since 0.1.60&quot;">​</a></h2><p>Click the CRON field in <strong>Triggers → Schedule</strong>. The popup offers <strong>Wizard / Simple / CRON</strong>, following the ioBroker dialogs. Simple builds intervals; Wizard also offers a specific time with numeric weekdays. CRON provides component tabs and optional seconds. <strong>OK</strong> applies a valid rule; <strong>Cancel</strong> and Escape preserve the previous value. Light/dark appearance and all DE/EN/FR dialog texts are supported.</p><p><img src="'+t+'" alt="Schedule"></p><p><img src="'+n+'" alt="CRON dialog"></p><p><img src="'+d+'" alt="Dark CRON dialog"></p><p>Five fields: minute, hour, day of month, month, weekday. Six fields start with seconds. Numbers, lists, ranges and steps are supported. Examples: <code>*/5 * * * *</code> every five minutes; <code>*/30 * * * * *</code> every 30 seconds; <code>30 7 * * 1-5</code> weekdays at 07:30. Sunday is 0 or 7. Home Assistant executes in its local time; no browser timer. Steps apply to clock fields: <code>*/7</code> minutes starts again at minute 0 each hour.</p><p>Output uses native <code>time_pattern</code> or <code>time</code> triggers with <code>weekday</code>. Month and day of month must be <code>*</code>. Dates, validity ranges, one-off events and astronomical day/night windows are not yet implemented in the dialog. Unsupported rules are explicitly rejected. Weekday rules expand to at most 2000 individual times; more frequent rules are rejected. Calendar triggers and HA conditions remain available separately. Project JSON retains the CRON rule; YAML retains its equivalent native HA structure.</p><table tabindex="0"><thead><tr><th>ioBroker trigger</th><th>Blocks for HA / HA equivalent</th></tr></thead><tbody><tr><td>If object / If objects</td><td>State trigger with one or multiple entities; from/to, attribute and hold time. No ioBroker object IDs.</td></tr><tr><td>Triggered by / acknowledge value</td><td>HA has no ioBroker <code>ack</code> equivalent here. No artificial acknowledgement block.</td></tr><tr><td>↪ Value / Message</td><td>New trigger-data value block: current/previous state, entity ID, trigger ID/type, MQTT payload/JSON and event data. Missing data returns <code>none</code>; convert numbers as needed.</td></tr><tr><td>Astro with offset</td><td>Sunrise/sunset with optional minute offset. Other sun conditions via native HA blocks.</td></tr><tr><td>Schedule / CRON</td><td>Dialog above, native HA execution. No dynamic registration of named ioBroker schedules.</td></tr><tr><td>Message received</td><td>MQTT or HA event trigger with filters; no direct ioBroker script-message receiver.</td></tr><tr><td>Log message</td><td>HA event trigger for <code>system_log_event</code>, when HA is configured to provide those events. No dedicated ioBroker log listener.</td></tr><tr><td>File/enum events</td><td>No direct implementation. Use an available HA integration and its events/entities.</td></tr><tr><td>Further native HA triggers</td><td>MQTT, template, webhook, device, tag, conversation, zone and geolocation are now directly in <strong>Triggers</strong>, without duplicates in HA advanced.</td></tr></tbody></table><p><img src="'+a+'" alt="Trigger data"></p><p>References: <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_trigger.ts" target="_blank" rel="noreferrer">original ioBroker trigger blocks</a>, <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">native HA triggers</a>. Appearance follows the original; execution and data remain specific to HA.</p><p>Since <strong>0.1.11</strong>, the category includes seven additional blocks. <a href="./blocks#date-and-time-added-in-0-1-11">All blocks with images</a>. The editor uses the original Blockly library; HA Jinja generation is an original UGSo implementation. References: <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_time.ts" target="_blank" rel="noreferrer">ioBroker JavaScript adapter time blocks</a> and <a href="https://docs.blockly.com/guides/create-custom-blocks/define/block-definitions/" target="_blank" rel="noreferrer">Blockly block definitions</a>.</p><h2 id="iobroker-blocks-for-ha" tabindex="-1">ioBroker / Blocks for HA <a class="header-anchor" href="#iobroker-blocks-for-ha" aria-label="Permalink to &quot;ioBroker / Blocks for HA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ioBroker</th><th>Our block / implementation</th></tr></thead><tbody><tr><td>Current time comparison with fixed clock time</td><td><strong>Clock comparison</strong>: less, less/equal, greater, greater/equal, equal, between and outside. End field appears for periods.</td></tr><tr><td>Current time checkbox and plugged-in value</td><td><strong>Clock comparison with inputs</strong>: text blocks for start/end. Uncheck current time to expose a datetime socket.</td></tr><tr><td>Current time as Date object or formatted value</td><td><strong>Current datetime</strong> plus separate <strong>formatter</strong>, preventing formatted text from entering datetime calculations.</td></tr><tr><td>Calculated time</td><td><strong>Calendar start</strong>: today, tomorrow, week (Monday), month and year. Other ioBroker calendar boundaries are not implemented yet.</td></tr><tr><td>Astro event time with offset</td><td><strong>Next sun event</strong>: rise, set, dawn, dusk, solar noon and midnight, with positive/negative minute offset.</td></tr><tr><td>Calculate time, base ± number and unit</td><td><strong>Shift datetime</strong>: datetime ± number; milliseconds, seconds, minutes, hours or days.</td></tr></tbody></table><h2 id="connections-and-use" tabindex="-1">Connections and use <a class="header-anchor" href="#connections-and-use" aria-label="Permalink to &quot;Connections and use&quot;">​</a></h2><p>Comparisons return <strong>Boolean</strong>, fitting conditions, AND/OR/NOT and If. Datetimes have a typed <strong>Time connection</strong>: current time, calendar start, sun event and time calculation can nest. Numeric blocks supply offset/amount; formatted clock text supplies comparison boundaries. Formatting supports HH:mm, HH:mm:ss, ISO date, German date, date/time, ISO with timezone and Unix seconds.</p><p>Example: <strong>Current datetime → Shift datetime (+ 30 minutes) → Format (HH:mm)</strong>, then assign to a variable:</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">now</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timedelta</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">minutes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">30)).</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">strftime</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%H:%M&quot;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Between 22:00 and 06:00</strong> includes the overnight period. Start is included, end excluded. Equal boundaries describe an empty period; outside is its complement. Fixed clock times must be HH:mm or HH:mm:ss. Dynamic text boundaries must provide the same format at runtime; invalid values cause an HA template error. Comparison has second precision: equal 12:00 means 12:00:00 and is not a reliable time trigger.</p><h2 id="execution-and-limitations" tabindex="-1">Execution and limitations <a class="header-anchor" href="#execution-and-limitations" aria-label="Permalink to &quot;Execution and limitations&quot;">​</a></h2><p>Templates execute <strong>in Home Assistant</strong>. The browser builds YAML and does not run a scheduling engine. Functions use HA&#39;s configured timezone: <a href="https://www.home-assistant.io/template-functions/#date-time" target="_blank" rel="noreferrer">HA date/time functions</a>. Calendar starts use local midnight; day arithmetic follows the local calendar, including DST changes. Adding 24 hours does not guarantee 24 elapsed UTC hours across a timezone transition.</p><p>Sun values come from <a href="https://www.home-assistant.io/integrations/sun/#sensors" target="_blank" rel="noreferrer">HA Sun integration attributes</a>. They represent the <strong>next event</strong>, which may be tomorrow. UTC values are converted to HA local time before calculation/formatting. Missing values, such as an unavailable integration or uncomputable event, cause a template error rather than a fabricated fallback time.</p><p>A comparison checks the clock <strong>when its condition is evaluated</strong>. It does not start the automation or wait for the target time. Use a time or sun trigger for that. The new sun value block does not replace a sun trigger.</p><p><strong>Blocks project JSON</strong> preserves block shapes, selections and dynamic sockets. <strong>Opening YAML</strong> retains the time templates but displays them as general template blocks. A datetime previously assigned to an HA variable may become text; our variable getter therefore has no Time connection. Nest datetime blocks directly or, since <strong>0.1.12</strong>, connect the getter through <strong>To datetime</strong>. <a href="./conversion">Conversion and units</a>. Converted runtime numbers now also fit datetime amounts and sun offsets.</p><p>Verification covers Blockly/YAML roundtrips, typed connections, dynamic fields and Jinja checks for overnight boundaries and DST. Execution on a real HA system has not been verified.</p>',25)])])}const v=i(l,[["render",c]]);export{f as __pageData,v as default};
